```sql
/* Выбираем заведения (буфеты и кофейни), работающие в интервале 7:30–16:00 */
SELECT DISTINCT
    r."name",
    r."address",
    r."service_format",
    r."hours"
FROM "restaurant" r
WHERE (
        LOWER(r."service_format") LIKE '%buffet%'
        OR LOWER(r."service_format") LIKE '%coffee%'
      )
  /* Условие: открытие не позже 07:30 и закрытие не раньше 16:00 */
  AND (
        /* Время открытия извлекаем из строки hours */
        (SUBSTRING(r."hours" FROM '(\d{1,2}:\d{2})')::time <= TIME '07:30')
        AND
        /* Время закрытия — последнее время в строке */
        (SUBSTRING(r."hours" FROM '(\d{1,2}:\d{2})(?!.*\d{1,2}:\d{2})')::time >= TIME '16:00')
      )
ORDER BY r."name" ASC NULLS FIRST;
```

